import json, html

data = json.load(open('/tmp/disc_data.json', encoding='utf-8'))
assert len(data) == 24
step_names = ['Первый','Второй','Третий','Четвёртый','Пятый','Шестой','Седьмой','Восьмой']
types = [
    ('d', 'D', 'Доминирование', 'Dominance'),
    ('i', 'I', 'Влияние', 'Influence'),
    ('s', 'S', 'Стабильность', 'Stability'),
    ('c', 'C', 'Соответствие', 'Compliance'),
]

tabs = []
for i, name in enumerate(step_names):
    selected = 'true' if i == 0 else 'false'
    active = ' is-active' if i == 0 else ''
    tabindex = '0' if i == 0 else '-1'
    tabs.append(
        f'<button class="disc-tab{active}" type="button" role="tab" id="tabbtn{i}" '
        f'aria-controls="tab{i+1}" aria-selected="{selected}" tabindex="{tabindex}" '
        f'data-step-btn="{i}"><span class="disc-tab__num">{i+1}</span><span>{name}</span></button>'
    )

panes = []
for step in range(8):
    cards = []
    for k in range(3):
        idx = step * 3 + k
        q = data[idx]
        lis = []
        for item in q['items']:
            lis.append(f'<li class="disc-item" data-type="{item["type"]}">{html.escape(item["text"])}</li>')
        card_no = idx + 1
        cards.append(f'''<div class="disc-card" role="group" aria-label="Вопрос {card_no}">
            <div class="disc-card__title">Я наиболее</div>
            <ul class="disc-list" id="draggable-list{idx+1}" data-list="{idx}" aria-label="Вопрос {card_no}: от наиболее похожего к наименее похожему">
              {''.join(lis)}
            </ul>
            <div class="disc-card__foot">Я наименее</div>
          </div>''')
    active = ' is-active' if step == 0 else ''
    hidden = '' if step == 0 else ' hidden'
    panes.append(f'''<div class="disc-pane{active}" data-step-pane="{step}" id="tab{step+1}" role="tabpanel" aria-labelledby="tabbtn{step}"{hidden}>
          <div class="disc-grid3">
          {''.join(cards)}
          </div>
        </div>''')

result_cards = []
for key, letter, name, en in types:
    result_cards.append(f'''<div class="result-card" data-type="{key}">
            <div class="result-card__head">
              <span class="result-card__letter" aria-hidden="true">{letter}</span>
              <div>
                <div class="result-card__name">{name}</div>
                <div class="result-card__en">{en}</div>
              </div>
            </div>
            <div class="result-card__value" data-score-value>0</div>
            <div class="result-card__bar" aria-hidden="true"><span data-score-bar></span><i></i></div>
          </div>''')

