<script>
(() => {
  'use strict';

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

  const TOTAL_STEPS = 8;
  const LAST_STEP = TOTAL_STEPS - 1;
  const SCALE = 24;
  const GRIP_SVG = '<svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false"><path fill="currentColor" d="M5 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm0 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm0 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm4-8a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm0 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm0 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z"/></svg>';

  const wizard = $('#wizardmodal');
  const result = $('#result');
  const root = $('#rootwizard');
  const tabs = $$('[data-step-btn]', wizard);
  const tabsWrap = $('.disc-modal__tabs-wrap', wizard) || $('.disc-modal__tabs', wizard);
  const panes = $$('[data-step-pane]', wizard);
  const btnPrev = $('[data-disc-prev]', wizard);
  const btnNext = $('[data-disc-next]', wizard);
  const btnFinish = $('[data-disc-finish]', wizard);
  const progress = $('#discProgress');
  const progressBar = $('.disc-progress', wizard);
  const stepLabel = $('#stepLabel');
  const progressPct = $('#progressPct');
  const live = $('#live');
  const scoreLine = $('#scoreLine');

  const lists = $$('.disc-list', root);
  const initialOrder = new Map(lists.map((list) => [list, $$('.disc-item', list)]));
  let step = 0;

  // Add a drag handle to every item once. Handles are keyboard-operable.
  lists.forEach((list) => {
    $$('.disc-item', list).forEach((item) => {
      if ($('.disc-handle', item)) return;
      const text = (item.textContent || '').trim();
      const handle = document.createElement('button');
      handle.type = 'button';
      handle.className = 'disc-handle';
      handle.setAttribute('aria-label', 'Перетащить «' + text + '». Стрелки вверх и вниз меняют позицию.');
      handle.innerHTML = GRIP_SVG;
      handle.addEventListener('keydown', onHandleKeydown);
      item.appendChild(handle);
    });
    list.addEventListener('dragstart', (event) => event.preventDefault());
  });

  function itemLabel(item) {
    return (item.textContent || '').replace(/\\s+/g, ' ').trim();
  }

  function announcePosition(item) {
    if (!item || !item.parentElement) return;
    const items = $$('.disc-item', item.parentElement);
    const position = items.indexOf(item) + 1;
    live.textContent = '«' + itemLabel(item) + '» — позиция ' + position + ' из ' + items.length + '.';
  }

  function onHandleKeydown(event) {
    const keys = ['ArrowUp', 'ArrowDown', 'Home', 'End'];
    if (keys.indexOf(event.key) === -1) return;
    const handle = event.currentTarget;
    const item = handle.closest('.disc-item');
    const list = item ? item.parentElement : null;
    if (!list) return;
    event.preventDefault();
    if (event.key === 'ArrowUp' && item.previousElementSibling) {
      list.insertBefore(item, item.previousElementSibling);
    } else if (event.key === 'ArrowDown' && item.nextElementSibling) {
      list.insertBefore(item.nextElementSibling, item);
    } else if (event.key === 'Home' && item.previousElementSibling) {
      list.insertBefore(item, list.firstElementChild);
    } else if (event.key === 'End' && item.nextElementSibling) {
      list.appendChild(item);
    } else {
      return;
    }
    announcePosition(item);
    handle.focus({ preventScroll: true });
  }

  function centerActiveTab() {
    if (!tabsWrap || !tabs[step]) return;
    const active = tabs[step];
    const left = active.offsetLeft - (tabsWrap.clientWidth - active.offsetWidth) / 2;
    const max = Math.max(0, tabsWrap.scrollWidth - tabsWrap.clientWidth);
    const target = Math.max(0, Math.min(max, left));
    if (Math.abs(tabsWrap.scrollLeft - target) > 2) {
      tabsWrap.scrollTo({ left: target, behavior: 'smooth' });
    }
  }

  function render() {
    tabs.forEach((tab) => {
      const active = Number(tab.dataset.stepBtn) === step;
      tab.classList.toggle('is-active', active);
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
      tab.tabIndex = active ? 0 : -1;
    });
    panes.forEach((pane) => {
      const active = Number(pane.dataset.stepPane) === step;
      pane.classList.toggle('is-active', active);
      pane.hidden = !active;
    });
    if (btnPrev) btnPrev.disabled = step === 0;
    if (btnNext) btnNext.hidden = step === LAST_STEP;
    if (btnFinish) btnFinish.hidden = step !== LAST_STEP;
    const percent = ((step + 1) / TOTAL_STEPS) * 100;
    if (progress) progress.style.width = percent + '%';
    if (progressBar) {
      progressBar.setAttribute('aria-valuenow', String(step + 1));
      progressBar.setAttribute('aria-valuetext', 'Шаг ' + (step + 1) + ' из ' + TOTAL_STEPS);
    }
    if (stepLabel) stepLabel.textContent = 'Шаг ' + (step + 1) + ' из ' + TOTAL_STEPS;
    if (progressPct) progressPct.textContent = Math.round(percent) + '%';
    root.dataset.step = String(step);
    requestAnimationFrame(centerActiveTab);
  }

  function go(next) {
    const target = Math.max(0, Math.min(LAST_STEP, next));
    if (target === step) {
      render();
      return;
    }
    step = target;
    render();
    if (wizard.getBoundingClientRect().top < 0) {
      wizard.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  tabs.forEach((tab) => {
    tab.addEventListener('click', () => go(Number(tab.dataset.stepBtn)));
  });

  if (tabsWrap) {
    tabsWrap.addEventListener('keydown', (event) => {
      const keys = ['ArrowRight', 'ArrowLeft', 'Home', 'End'];
      if (keys.indexOf(event.key) === -1) return;
      event.preventDefault();
      let index = tabs.indexOf(document.activeElement);
      if (index < 0) index = step;
      let next = index;
      if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
      if (event.key === 'ArrowLeft') next = (index - 1 + tabs.length) % tabs.length;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = tabs.length - 1;
      go(next);
      tabs[next].focus({ preventScroll: true });
    });
  }

  if (btnPrev) btnPrev.addEventListener('click', () => go(step - 1));
  if (btnNext) btnNext.addEventListener('click', () => go(step + 1));
  if (btnFinish) btnFinish.addEventListener('click', showResult);

  // ---------- pointer drag & drop (mouse, touch, pen) ----------
  let pending = null;
  let drag = null;

  function onPointerDown(event) {
    if (event.button != null && event.button !== 0) return;
    if (drag || pending) return;
    const item = event.target.closest('.disc-item');
    if (!item) return;
    const list = item.parentElement;
    if (!list || !list.classList.contains('disc-list')) return;
    const isCoarse = event.pointerType === 'touch' || event.pointerType === 'pen';
    const handle = event.target.closest('.disc-handle');
    if (isCoarse && !handle) return;

    pending = {
      item: item,
      list: list,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      rect: item.getBoundingClientRect()
    };
    event.preventDefault();
    window.addEventListener('pointermove', onPointerMove, { passive: false });
    window.addEventListener('pointerup', onPointerUp);
    window.addEventListener('pointercancel', onPointerUp);
  }

  function onPointerMove(event) {
    if (pending && !drag) {
      if (event.pointerId !== pending.pointerId) return;
      const dx = event.clientX - pending.startX;
      const dy = event.clientY - pending.startY;
      if (Math.sqrt(dx * dx + dy * dy) < 5) return;
      startDrag(event);
      return;
    }
    if (!drag || event.pointerId !== drag.pointerId) return;
    event.preventDefault();
    moveDrag(event.clientX, event.clientY);
  }

  function startDrag(event) {
    const p = pending;
    const ghost = p.item.cloneNode(true);
    ghost.classList.add('drag-ghost');
    ghost.classList.remove('is-placeholder');
    ghost.setAttribute('aria-hidden', 'true');
    $$('.disc-handle', ghost).forEach((handle) => { handle.tabIndex = -1; });
    ghost.style.width = p.rect.width + 'px';
    ghost.style.height = p.rect.height + 'px';
    ghost.style.left = p.rect.left + 'px';
    ghost.style.top = p.rect.top + 'px';
    document.body.appendChild(ghost);
    p.item.classList.add('is-placeholder');
    p.list.classList.add('is-reordering');
    document.body.classList.add('is-dragging');
    drag = {
      item: p.item,
      list: p.list,
      ghost: ghost,
      pointerId: p.pointerId,
      startX: p.startX,
      startY: p.startY
    };
    pending = null;
    moveDrag(event.clientX, event.clientY);
    live.textContent = 'Перетаскивание: «' + itemLabel(p.item) + '».';
  }

  function moveDrag(x, y) {
    if (!drag) return;
    drag.ghost.style.transform = 'translate3d(' + (x - drag.startX) + 'px,' + (y - drag.startY) + 'px,0)';

    const list = drag.list;
    const item = drag.item;
    const others = $$('.disc-item', list).filter((other) => other !== item);
    let before = null;
    for (const other of others) {
      const rect = other.getBoundingClientRect();
      if (y < rect.top + rect.height / 2) {
        before = other;
        break;
      }
    }
    if (before) {
      if (item.nextElementSibling !== before) list.insertBefore(item, before);
    } else if (item.nextElementSibling) {
      list.appendChild(item);
    }

    const margin = 64;
    if (y < margin) window.scrollBy(0, -10);
    else if (y > window.innerHeight - margin) window.scrollBy(0, 10);
  }

  function onPointerUp(event) {
    if (drag && (event.pointerId == null || event.pointerId === drag.pointerId)) {
      const item = drag.item;
      const list = drag.list;
      drag.ghost.remove();
      item.classList.remove('is-placeholder');
      list.classList.remove('is-reordering');
      document.body.classList.remove('is-dragging');
      drag = null;
      announcePosition(item);
    }
    if (pending && (event.pointerId == null || event.pointerId === pending.pointerId)) {
      pending = null;
    }
    if (!drag && !pending) {
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
    }
  }

  if (root) root.addEventListener('pointerdown', onPointerDown);

  // ---------- scoring ----------
  function computeScore() {
    const score = { d: 0, i: 0, s: 0, c: 0 };
    lists.forEach((list) => {
      const items = $$('.disc-item', list);
      if (!items.length) return;
      const first = items[0].dataset.type;
      const last = items[items.length - 1].dataset.type;
      if (Object.prototype.hasOwnProperty.call(score, first)) score[first] += 1;
      if (Object.prototype.hasOwnProperty.call(score, last)) score[last] -= 1;
    });
    return score;
  }

  function showResult() {
    if (!result) return;
    const score = computeScore();
    if (scoreLine) {
      scoreLine.textContent = 'D:' + score.d + ', I:' + score.i + ', S:' + score.s + ', C:' + score.c;
    }
    $$('.result-card', result).forEach((card) => {
      const type = card.dataset.type;
      const value = score[type] || 0;
      const valueEl = $('[data-score-value]', card);
      const bar = $('[data-score-bar]', card);
      if (valueEl) valueEl.textContent = String(value);
      if (bar) {
        const width = Math.min(50, (Math.abs(value) / SCALE) * 50);
        bar.style.width = width + '%';
        bar.style.left = value >= 0 ? '50%' : (50 - width) + '%';
      }
      card.classList.toggle('is-negative', value < 0);
    });
    wizard.hidden = true;
    result.hidden = false;
    window.scrollTo({ top: 0, behavior: 'smooth' });
    live.textContent = 'Тест завершён. Ваш DISC-профиль: ' + (scoreLine ? scoreLine.textContent : '');
  }

  function restart() {
    initialOrder.forEach((items, list) => {
      items.forEach((item) => list.appendChild(item));
    });
    step = 0;
    result.hidden = true;
    wizard.hidden = false;
    render();
    window.scrollTo({ top: 0, behavior: 'smooth' });
    live.textContent = 'Тест начат заново.';
  }

  const restartButton = $('#restart');
  if (restartButton) restartButton.addEventListener('click', restart);

  render();
})();
</script>
</body>
</html>
