async function waitJson(url){for(let i=0;i<80;i++){try{const r=await fetch(url);if(r.ok)return r.json();}catch(_){}await sleep(150);}throw new Error('timeout');}
(async()=>{
 try{
  await waitJson(`http://127.0.0.1:${port}/json/version`);
  const target=await (await fetch(`http://127.0.0.1:${port}/json/new?file:///tmp/index.html`,{method:'PUT'})).json();
  const ws=new WebSocket(target.webSocketDebuggerUrl); let id=0; const pending=new Map(); const events=[];
  ws.onmessage=ev=>{const m=JSON.parse(ev.data); if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(JSON.stringify(m.error))):p.resolve(m.result);}else if(m.method)events.push(m);};
  await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej;});
  const send=(method,params={})=>new Promise((res,rej)=>{const mid=++id;pending.set(mid,{resolve:res,reject:rej});ws.send(JSON.stringify({id:mid,method,params}));});
  const ev=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.text);return r.result.value;};
  await send('Runtime.enable'); await send('Page.enable'); await send('Log.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:375,height:812,deviceScaleFactor:2,mobile:true});
  await send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:5});
  await send('Page.navigate',{url:'file:///tmp/index.html'}); await sleep(1200);
  const mobile=await ev(`(() => ({
    innerWidth: innerWidth,
    clientWidth: document.documentElement.clientWidth,
    scrollWidth: document.documentElement.scrollWidth,
    tabbarScrollWidth: document.querySelector('.disc-modal__tabs-wrap').scrollWidth,
    tabbarClientWidth: document.querySelector('.disc-modal__tabs-wrap').clientWidth,
    tabs: Array.from(document.querySelectorAll('.disc-tab')).map(t=>t.textContent),
    cardRects: Array.from(document.querySelectorAll('.disc-pane.is-active .disc-card')).map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),w:Math.round(r.width),h:Math.round(r.height)}}),
    handles: Array.from(document.querySelectorAll('.disc-pane.is-active .disc-handle')).map(h=>{const r=h.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}}).slice(0,2),
    overflowEls: Array.from(document.querySelectorAll('body *')).filter(e=>{const r=e.getBoundingClientRect();return r.right > innerWidth + 1 && getComputedStyle(e).position !== 'fixed'}).slice(0,5).map(e=>e.className||e.tagName)
  }))()`);
  console.log('MOBILE LAYOUT',JSON.stringify(mobile,null,2));

  // touch drag via handle of first item
  const rects=await ev(`(() => {
    const h=document.querySelector('#draggable-list1 .disc-item .disc-handle');
    const items=Array.from(document.querySelectorAll('#draggable-list1 .disc-item'));
    const hr=h.getBoundingClientRect();
    return {handle:{x:hr.x+hr.width/2,y:hr.y+hr.height/2}, items:items.map(x=>{const r=x.getBoundingClientRect();return {top:r.top,bottom:r.bottom,y:r.y+r.height/2}}), before:items.map(x=>x.dataset.type)};
  })()`);
  const hx=rects.handle.x, hy=rects.handle.y, ty=rects.items[3].bottom-1;
  const touch=(type,x,y)=>send('Input.dispatchTouchEvent',{type,touchPoints: type==='touchEnd'?[]:[{x,y,radiusX:2,radiusY:2,force:1}],modifiers:0});
  await touch('touchStart',hx,hy); await sleep(80);
  for(let i=1;i<=12;i++){await touch('touchMove',hx,hy+(ty-hy)*i/12);await sleep(25);}
  await touch('touchEnd',hx,ty); await sleep(400);
  const touchOrder=await ev(`({after:Array.from(document.querySelectorAll('#draggable-list1 .disc-item')).map(x=>x.dataset.type), live:document.querySelector('#live').textContent, ghost:!!document.querySelector('.drag-ghost'), dragging:document.body.classList.contains('is-dragging')})`);
  console.log('TOUCH DRAG',JSON.stringify({before:rects.before,...touchOrder},null,2));

  // keyboard reorder
  const kb=await ev(`(() => {
    const item=document.querySelector('#draggable-list2 .disc-item');
    const h=item.querySelector('.disc-handle');
    h.focus();
    const before=Array.from(document.querySelectorAll('#draggable-list2 .disc-item')).map(x=>x.dataset.type);
    h.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true,cancelable:true}));
    const after=Array.from(document.querySelectorAll('#draggable-list2 .disc-item')).map(x=>x.dataset.type);
    return {before,after,focus:document.activeElement.className,live:document.querySelector('#live').textContent};
  })()`);
  console.log('KEYBOARD',JSON.stringify(kb,null,2));

  // jump to last step via tab click and inspect result at mobile
  await ev(`document.querySelector('[data-step-btn="7"]').click()`); await sleep(300);
  await ev(`document.querySelector('[data-disc-finish]').click()`); await sleep(500);
  const mobileResult=await ev(`(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    score: document.querySelector('.result__score span').textContent,
    cards: Array.from(document.querySelectorAll('.result-card')).map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),w:Math.round(r.width)}}),
    rects: Array.from(document.querySelectorAll('.result-card')).map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}})
  }))()`);
  console.log('MOBILE RESULT',JSON.stringify(mobileResult,null,2));
  const errors=events.filter(e=>e.method==='Log.entryAdded'&&e.params.entry.level==='error').map(e=>e.params.entry.text);
  console.log('ERRORS',JSON.stringify(errors));
  ws.close();
 }catch(e){console.error('ERR',e);process.exitCode=1;}finally{chrome.kill('SIGKILL');}
})();
